// Logo mitra RRI untuk strip marquee landing page (PR landing-logo-mitra, 2026-11-18).
//
// Sumber: 10 file logo yang DIUNGGAH PENGGUNA (bukan unduhan web), di-embed
// sebagai data URI base64 karena push snapshot GitHub hanya menerima file
// teks (pola yang sama seperti logoDeals.ts / logoRriLanding.ts).
//
// Pemrosesan (PIL, dari file asli): trim ke isi logo (bbox alpha untuk
// logo transparan, bbox non-putih untuk logo berlatar putih), resize ke
// tinggi 96px (tampil h-10 = 40px, ~2.4x untuk layar retina), format
// terkecil per logo (PNG optimize vs WebP q85). TIDAK ADA logo yang
// berlatar hitam pekat: yang tampak hitam di pratinjau unggahan adalah
// latar TRANSPARAN yang dirender gelap oleh penampil gambar — semua logo
// sudah transparan/putih, jadi tidak perlu chip putih; penyatuan warna
// dilakukan di CSS (grayscale + opacity) di Marklo.tsx, mengikuti
// screenshot referensi pengguna (wordmark slate redup di latar putih).
//
// Logo dipakai apa adanya, tidak diwarnai ulang — filter grayscale CSS
// hanya menyamakan tampilannya di strip, seperti wordmark template.

export interface LogoMitra {
  /** Nama mitra — dipakai sebagai alt text dan label aksesibilitas. */
  nama: string;
  /** Data URI lengkap hasil embed (PNG/WebP base64). */
  logoDataUri: string;
}

